@(require "common.rkt"
          (for-label file/cache))

@title[#:tag "cache"]{Caching}

@defmodule[file/cache]{The @racketmodname[file/cache] library provides
utilities for managing a local cache of files, such as downloaded
files.  The cache is safe for concurrent use across processes, since
it uses filesystem locks, and it isolates clients from filesystem
failures.}

@defproc[(cache-file     [dest-file path-string?]
                         [#:exists-ok? exists-ok? any/c #f]
                         [key (not/c #f)]
                         [cache-dir path-string?]
                         [fetch (-> any)]
                         [#:notify-cache-use notify-cache-use (string? . -> . any)
                                             void]
                         [#:max-cache-files max-files real? 1024]
                         [#:max-cache-size max-size real? (* 64 1024 1024)]
                         [#:evict-before? evict-before? (hash? hash? . -> . boolean?)
                                          (lambda (a b)
                                            (< (hash-ref a 'modify-seconds)
                                               (hash-ref b 'modify-seconds)))]
                         [#:log-error-string log-error-string (string? . -> . any)
                                             (lambda (s) (log-error s))]
                         [#:log-debug-string log-debug-string (string? . -> . any)
                                             (lambda (s) (log-debug s))])
           void?]{

Looks for a file in @racket[cache-dir] previously cached with
@racket[key], and copies it to @racket[dest-file] (which must not
exist already, unless @racket[exists-ok?] is true) if a cached file
is found. Otherwise, @racket[fetch] is called; if @racket[dest-file]
exists after calling @racket[fetch], it is copied to @racket[cache-dir]
and recorded with @racket[key]. When a cache entry is used,
@racket[notify-cache-use] is called with the name of the cache file.

When a new file is cached, @racket[max-files] (as a file count) and
@racket[max-size] (in bytes) determine whether any previously cached
files should be evicted from the cache. If so, @racket[evict-before?]
determines an order on existing cache entries for eviction; each
argument to @racket[evict-before?] is a hash table with at least the
following keys:

@itemlist[

 @item{@racket['modify-seconds] --- the file's modification date}

 @item{@racket['size] --- the file's size in bytes}

 @item{@racket['key] --- the cache entry's key}

 @item{@racket['name] --- the cache file's name}

]

The @racket[log-error-string] and @racket[log-debug-string] functions
are used to record errors and debugging information.}


@defproc[(cache-remove [key any/c]
                       [cache-dir path-string?]
                       [#:log-error-string log-error-string (string? . -> . any)
                                           (lambda (s) (log-error s))]
                       [#:log-debug-string log-debug-string (string? . -> . any)
                                           (lambda (s) (log-debug s))])
          void?]{

Removes the cache entry matching @racket[key] (if any) from the cache
in @racket[cache-dir], or removes all cached files if @racket[key] is
@racket[#f].

The @racket[log-error-string] and @racket[log-debug-string] functions
are used to record errors and debugging information.}

#lang scribble/doc
@(require scribble/manual
          (for-label file/convertible racket/base racket/contract))

@title[#:tag "convertible"]{Convertible: Data-Conversion Protocol}

@defmodule[file/convertible]

The @racketmodname[file/convertible] library provides a protocol to
mediate between providers of data in different possible formats and
consumers of the formats. For example, a datatype that implements
@racket[prop:convertible] might be @deftech{convertible} to a GIF or
PDF stream, in which case it would produce data for
@racket['gif-bytes] or @racket['pdf-bytes] requests.

Any symbol can be used for a conversion request, but the following
should be considered standard:

@itemlist[
 #:style 'compact

 @item{@racket['text] --- a string for human-readable text}
 @item{@racket['gif-bytes] --- a byte string containing a GIF image encoding}
 @item{@racket['png-bytes] --- a byte string containing a PNG image encoding}
 @item{@racket['png-bytes+bounds] --- a list containing a byte string and four numbers;
        the byte string contains a PNG document, and the four numbers
        are sizing information for the image: the width, height,
        descent (included in the height), and extra vertical top space
        (included in the height), in that order}
 @item{@racket['png-bytes+bounds8] --- a list containing a byte string
        and eight numbers; like @racket['png-bytes+bounds], but where
        the image encoded that is in the byte string can be padded in
        each direction (to allow the drawn region to extend beyond
        its ``bounding box''), where the extra four numbers in the
        list specify the amount of padding that was added to the
        image: left, right, top, and bottom}
 @item{@racket['png@2x-bytes] --- like @racket['png-bytes], but for an
        image that is intended for drawing at @racket[1/2] scale}
 @item{@racket['png@2x-bytes+bounds] --- like
        @racket['png-bytes+bounds], but for an image that is intended
        for drawing at @racket[1/2] scale, where the numbers in the result
        list are already scaled (e.g, the byte string encodes an image that
        is twice as wide as the first number in the resulting list)}
 @item{@racket['png@2x-bytes+bounds8] --- like @racket['png-bytes+bounds8],
        but but for an image that is intended for drawing at
        @racket[1/2] scale, and where the numbers in the result
        list are already scaled}
 @item{@racket['svg-bytes] --- a byte string containing a SVG image encoding}
 @item{@racket['svg-bytes+bounds] --- like @racket['png-bytes+bounds], but
        for an SVG image}
 @item{@racket['svg-bytes+bounds8] --- like @racket['png-bytes+bounds8], but
        for an SVG image}
 @item{@racket['ps-bytes] --- a byte string containing a PostScript document}
 @item{@racket['eps-bytes] --- a byte string containing an Encapsulated PostScript
        document}
 @item{@racket['eps-bytes+bounds] --- like @racket['png-bytes+bounds], but,
        but for an Encapsulated PostScript document}
 @item{@racket['eps-bytes+bounds8] --- like @racket['png-bytes+bounds8], but,
        but for an Encapsulated PostScript document}
 @item{@racket['pdf-bytes] --- a byte string containing a PDF document}
 @item{@racket['pdf-bytes+bounds] --- like @racket['png-bytes+bounds], but,
        but for an PDF document}
 @item{@racket['pdf-bytes+bounds8] --- like @racket['png-bytes+bounds8], but,
        but for an PDF document}
]

@defthing[prop:convertible
          (struct-type-property/c
           (->i ([v convertible?] [request symbol?] [default default/c])
                [result
                 (case request
                   [(text)
                    (or/c string? default/c)]
                   [(gif-bytes
                     png-bytes
                     png@2x-bytes
                     ps-bytes
                     eps-bytes
                     pdf-bytes
                     svg-bytes)
                    (or/c bytes? default/c)]
                   [(png-bytes+bounds
                     png@2x-bytes+bounds
                     eps-bytes+bounds
                     pdf-bytes+bounds)
                    (or/c (list/c bytes?
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?)))
                          default/c)]
                   [(png-bytes+bounds8
                     png@2x-bytes+bounds8
                     eps-bytes+bounds8
                     pdf-bytes+bounds8)
                    (or/c (list/c bytes?
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?))
                                  (and/c real? (not/c negative?)))
                          default/c)]
                   [else (or/c opaque-default/c any/c)])]))]{

A property whose value is invoked by @racket[convert].

The @racket[_v] argument to the procedure is the
structure, the @racket[_request] argument is a symbol for the requested
conversion, and the @racket[_default] argument is a value to return (typically
@racket[#f] if the conversion is not supported). The procedure's result
depends on the requested conversion, as above.

The @racket[default/c] contract is one generated by @racket[new-∀/c].}

@defproc[(convertible? [v any/c]) boolean?]{

Returns @racket[#t] if @racket[v] supports the conversion protocol,
@racket[#f] otherwise.}

@defproc[(convert [v convertible?] [request symbol?] [default any/c #f])
         (case request
           [(text)
            (or/c string? default/c)]
           [(gif-bytes
             png-bytes
             png@2x-bytes
             ps-bytes
             eps-bytes
             pdf-bytes
             svg-bytes)
            (or/c bytes? default/c)]
           [(png-bytes+bounds
             png@2x-bytes+bounds
             eps-bytes+bounds
             pdf-bytes+bounds)
            (or/c (list/c bytes?
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?)))
                  default/c)]
           [(png-bytes+bounds8
             png@2x-bytes+bounds8
             eps-bytes+bounds8
             pdf-bytes+bounds8)
            (or/c (list/c bytes?
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?))
                          (and/c real? (not/c negative?)))
                  default/c)]
           [else (or/c opaque-default/c any/c)])]{

Requests a data conversion from @racket[v], where @racket[request]
indicates the type of requested data and @racket[default] is the value
that the converter should return if it cannot produce data in the
format indicated by @racket[request].

The @racket[default/c] contract is one created by @racket[new-∀/c]
and it guarantees that the result of @racket[convert] is the given
default argument (or @racket[#f] if one is not supplied).}

#lang scribble/doc
@(require "common.rkt"
          scribble/extract
          (for-label file/gif))

@title[#:tag "gif"]{GIF File Writing}

@defmodule[file/gif]

The @racketmodname[file/gif] library provides functions for
writing GIF files to a stream, including GIF files with multiple
images and controls (such as animated GIFs).

A GIF stream is created by @racket[gif-start], and then individual
images are written with @racket[gif-add-image]. Optionally,
@racket[gif-add-control] inserts instructions for rendering the
images. The @racket[gif-end] function ends the GIF stream.

A GIF stream can be in any one of the following states:

@itemize[

 @item{@racket['init] : no images or controls have been added to the
       stream}

 @item{@racket['image-or-control] : another image or control can be
       written}

 @item{@racket['image] : another image can be written (but not a
       control, since a control was written)}

 @item{@racket['done] : nothing more can be added}

]


@defproc[(gif-stream? [v any/c]) boolean?]{
 Returns @racket[#t] if @racket[v] is a GIF stream created by
 @racket[gif-write], @racket[#f] otherwise.
}

@defproc[(image-ready-gif-stream? [v any/c]) boolean?]{
 Returns @racket[#t] if @racket[v] is a GIF stream that is not in
 @racket['done] mode, @racket[#f] otherwise.}

@defproc[(image-or-control-ready-gif-stream? [v any/c]) boolean?]{
 Returns @racket[#t] if @racket[v] is a GIF stream that is in
 @racket['init] or @racket['image-or-control] mode, @racket[#f]
 otherwise.}

@defproc[(empty-gif-stream? [v any/c]) boolean?]{
 Returns @racket[#t] if @racket[v] is a GIF stream that in
 @racket['init] mode, @racket[#f] otherwise.}

@defproc[(gif-colormap? [v any/c]) boolean?]{
  Returns @racket[#t] if @racket[v] represets a colormap,
  @racket[#f] otherwise.  A colormap is a list whose size is a power
  of @math{2} between @math{2^1} and @math{2^8}, and whose elements
  are vectors of size 3 containing colors (i.e., exact integers
  between @math{0} and @math{255} inclusive).}

@defproc[(color? [v any/c]) boolean?]{
  The same as @racket[byte?].}

@defproc[(dimension? [v any/c]) boolean?]{
 Returns @racket[#t] if @racket[v] is an exact integer between
 @racket[#x0] and @racket[#xFFFF] inclusive, @racket[#f]
 otherwise.}

@defproc[(gif-state [stream gif-stream?]) symbol?]{
 Returns the state of @racket[stream].}

@defproc[(gif-start [out output-port?]
                    [w dimension?]
                    [h dimension?]
                    [bg-color color?]
                    [cmap (or/c gif-colormap? #f)])
         gif-stream?]{

 Writes the start of a GIF file to the given output port, and
 returns a GIF stream that adds to the output port.

 The width and height determine a virtual space for the overall
 GIF image.  Individual images added to the GIF stream must fit
 within this virtual space.  The space is initialized by the
 given background color.

 Finally, the default meaning of color numbers (such as the
 background color) is determined by the given colormap, but
 individual images within the GIF file can have their own
 colormaps.

 A global colormap need not be supplied, in which case a
 colormap must be supplied for each image. Beware that
 @racket[bg-color] is ill-defined if a global colormap is not
 provided.}

@defproc[(gif-add-image [stream image-ready-gif-stream?]
                        [left dimension?]
                        [top dimension?]
                        [width dimension?]
                        [height dimension?]
                        [interlaced? any/c]
                        [cmap (or/c gif-colormap? #f)]
                        [bstr bytes?])
           void?]{

 Writes an image to the given GIF stream. The @racket[left],
 @racket[top], @racket[width], and @racket[height] values
 specify the location and size of the image within the overall
 GIF image's virtual space.

 If @racket[interlaced?] is true, then @racket[bstr] should
 provide bytes ininterlaced order instead of top-to-bottom
 order. Interlaced order is:

 @(itemize @item{every 8th row, starting with 0}
           @item{every 8th row, starting with 4}
           @item{every 4th row, starting with 2}
           @item{every 2nd row, starting with 1})

 If a global color is provided with @racket[gif-start], a
 @racket[#f] value can be provided for @racket[cmap].

 The @racket[bstr] argument specifies the pixel content of the
 image.  Each byte specifies a color (i.e., an index in the
 colormap).  Each row is provided left-to-right, and the rows
 provided either top-to-bottom or in interlaced order (see
 above).  If the image is prefixed with a control that specifies
 an transparent index (see @racket[gif-add-control]), then the
 corresponding ``color'' doesn't draw into the overall GIF
 image.

 An exception is raised if any byte value in @racket[bstr] is
 larger than the colormap's length, if the @racket[bstr] length
 is not @racket[width] times @racket[height], or if the
 @racket[top], @racket[left], @racket[width], and
 @racket[height] dimensions specify a region beyond the overall
 GIF image's virtual space.}

@defproc[(gif-add-control [stream image-or-control-ready-gif-stream?]
                          [disposal (or/c 'any 'keep 'restore-bg 'restore-prev)]
                          [wait-for-input? any/c]
                          [delay dimension?]
                          [transparent (or/c color? #f)])
         void?]{
 Writes an image-control command to a GIF stream. Such a control
 must appear just before an image, and it applies to the
 following image.

 The GIF image model involves processing images one by one,
 placing each image into the specified position within the
 overall image's virtual space. An image-control command can
 specify a delay before an image is added (to create animated
 GIFs), and it also specifies how the image should be kept or
 removed from the overall image before proceeding to the next
 one (also for GIF animation).

 The @racket[disposal] argument specifies how to proceed:

 @(itemize @item{@racket['any] : doesn't matter (perhaps because
                 the next image completely overwrites the
                 current one)}
           @item{@racket['keep] : leave the image in place}
           @item{@racket['restore-bg] : replace the image with
                 the background color}
           @item{@racket['restore-prev] : restore the overall
                 image content to the content before the image
                 is added})

 If @racket[wait-for-input?] is true, then the display program
 may wait for some cue from the user (perhaps a mouse click)
 before adding the image.

 The @racket[delay] argument specifies a delay in 1/100s of a
 second.

 If the @racket[transparent] argument is a color, then it
 determines an index that is used to represent transparent
 pixels in the follow image (as opposed to the color specified
 by the colormap for the index).

 An exception is raised if a control is already added to
 @racket[stream] without a corresponding image.}

@defproc[(gif-add-loop-control [stream empty-gif-stream?]
                               [iteration  dimension?])
         void?]{
 Writes a control command to a GIF stream for which no images or
 other commands have already been written. The command causes
 the animating sequence of images in the GIF to be repeated
 `iteration-dimension' times, where 0 can be used to mean
 ``infinity.''

 An exception is raise if some control or image has been added
 to the stream already.}

@defproc[(gif-add-comment [stream image-or-control-ready-gif-stream?]
                          [bstr bytes?])
         void?]{
 Adds a generic comment to the GIF stream.

 An exception is raised if an image-control command was just
 written to the stream (so that an image is required next).}

@defproc[(gif-end [stream image-or-control-ready-gif-stream?])
         void?]{
 Finishes writing a GIF file. The GIF stream's output port is
 not automatically closed.

 An exception is raised if an image-control command was just
 written to the stream (so that an image is required next).}

@defproc[(quantize [bstr (and/c bytes?
                                (lambda (bstr)
                                  (zero? (remainder (bytes-length bstr) 4))))])
         (values bytes? gif-colormap? (or/c color? #f))]{
 Each image in a GIF stream is limited to 256 colors, including the
 transparent ``color,'' if any. The @racket[quantize] function
 converts a 24-bit image (plus alpha channel) into an
 indexed-color image, reducing the number of colors if necessary.

 Given a set of pixels expressed in ARGB format (i.e., each four
 bytes is a set of values for one pixel: alpha, red, blue, and
 green), @racket[quantize] produces produces

  @(itemize @item{bytes for the image (i.e., a array of colors,
                  expressed as a byte string)}
            @item{a colormap}
            @item{either @racket[#f] or a color index for the
                         transparent ``color''})

 The conversion treats alpha values less than 128 as transparent
 pixels, and other alpha values as solid.

 The quantization process uses Octrees @cite["Gervautz1990"] to construct an adaptive
 palette for all (non-transparent) colors in the image.  This implementation is
 based on an article by Dean Clark @cite["Clark1996"]. 

 To convert a collection of images all with the same quantization,
 simply append them for the input of a single call of
 @racket[quantize], and then break apart the result bytes.}

#lang scribble/doc
@require["common.rkt"
         scribble/examples
         (for-label file/glob racket/sequence)]

@(define glob-eval (make-base-eval '(require file/glob)))

@title[#:tag "glob"]{Globbing}

@defmodule[file/glob]{The @racketmodname[file/glob] library implements
@hyperlink["https://en.wikipedia.org/wiki/Glob_(programming)"]{globbing}
for @racket[path-string?] values. A @emph{glob} is a path string that matches
a set of path strings using the following @deftech[#:key "glob-wildcard"]{wildcards}:
@itemlist[
@item{
  A sextile (@tt{*}) matches any sequence of characters in a file or directory
  name.
}
@item{
  Two sextiles (@tt{**}) match any sequence of characters and any number of
  path separators.
}
@item{
  A question mark (@tt{?}) matches any single character in a file or directory
  name.
}
@item{
  Square bracket-delimited character groups, e.g. @tt{[abc]}, match any
  character within the group. The square brackets have the same meaning in globs
  as in regular expressions, see
  @secref["regexp-syntax" #:doc '(lib "scribblings/reference/reference.scrbl")].
}
@item{
  If the glob ends with a path separator (@tt{/} on any @racket[(system-type)],
  additionally @tt{\} on @racket['windows])
  then it only matches directories.
}
]

@margin-note{On Windows, wildcards cannot be escaped because @tt{\} is a path separator.}

By default, wildcards will not match files or directories whose name begins
with a period (aka "dotfiles").  To override, set the parameter
@racket[glob-capture-dotfiles?] to a non-@racket[#f] value or supply a similar
value using the @racket[#:capture-dotfiles?] keyword.
}

@defthing[glob/c (or/c path-string? (sequence/c path-string?))]{
A @tech[#:doc '(lib "scribblings/reference/reference.scrbl")]{flat contract}
that accepts a glob or a sequence of globs.
}

All @racketmodname[file/glob] functions accept @racket[glob/c] values.
These functions also recognize braces (@tt|{{}}|) as a @deftech[#:key "glob-meta-wildcard"]{meta-wildcard} for
describing multiple globs.
@margin-note{Braces are interpreted @emph{before} any other wildcards.}

@itemlist[
@item{
Brace-delimited, comma-separated character groups, e.g. @tt|{{foo,bar}}|,
expand to multiple globs before the @racketmodname[file/glob] module begins
matching. For example, the @racket[glob/c] value @racket|{{foo,bar}.rkt}|
has the same meaning as @racket['("foo.rkt" "bar.rkt")].
}
]

@defproc[(glob [pattern glob/c] [#:capture-dotfiles? capture-dotfiles? boolean? (glob-capture-dotfiles?)]) (listof path?)]{
  Builds a list of all paths on the current filesystem that match any glob
  in @racket[pattern]. The order of paths in the result is unspecified.

  If @racket[pattern] contains the wildcard @tt{**}, then @racket[glob]
  recursively searches the filesystem to find matches.
  For example, the glob @racket{/**.rkt} will search the @emph{entire filesystem}
  for files or directories with a @racket{.rkt} suffix (aka, Racket files).

Examples:
@codeblock{
> (glob "*.rkt")
;; Lists all Racket files in current directory

> (glob "*/*.rkt")
;; Lists all Racket files in all sub-directories of the current directory.
;; (Does not search sub-sub-directories, etc.)

> (glob (build-path (find-system-path 'home-dir) "**" "*.rkt"))
;; Recursively searches home directory for Racket files, lists all matches.

> (glob "??.rkt")
;; Lists all Racket files in current directory with 2-character names.

> (glob "[a-z0-9].rkt")
;; Lists all Racket files in current directory with single-character,
;; alphanumeric names.

> (glob '("foo-bar.rkt" "foo-baz.rkt" "qux-bar.rkt" "qux-baz.rkt"))
;; Filters the list to contain only files or directories that exist.

> (glob "{foo,qux}-{bar,baz}.rkt")
;; Same as above, returns at most 4 files.
}
}

@defproc[(in-glob [pattern glob/c] [#:capture-dotfiles? capture-dotfiles? boolean? (glob-capture-dotfiles?)]) (sequence/c path?)]{
  Returns a stream of all paths matching the glob @racket[pattern],
  instead of eagerly building a list.
}

@defproc[(glob-match? [pattern glob/c]
                      [path path-string?]
                      [#:capture-dotfiles? capture-dotfiles? boolean? (glob-capture-dotfiles?)]) boolean?]{
  Analogous to @racket[regexp-match?]; returns @racket[#true] if @racket[path]
  matches any glob in @racket[pattern].

  @racket[(glob-match? pattern path)] is @emph{not} the same as:
  @racketblock[
    (member path (glob pattern))
  ]
  because @racket[glob] only returns files/directories that exist, whereas
  @racket[glob-match?] does not check that @racket[path] exists.

  This operation accesses the filesystem.
}

@defproc*[([(glob-quote [str string?]) string?]
           [(glob-quote [path path?]) path?]
)]{
  Escapes all @tech{glob wildcards} and @tech{glob meta-wildcards} in the given
  string or path string.

  @examples[#:eval glob-eval
    (glob-quote "*.rkt")
    (glob-quote "[Ff]ile?{zip,tar.gz}")
    (glob-quote "]")
  ]
}

@defparam[glob-capture-dotfiles? capture-dotfiles? boolean? #:value #f]{
  Determines whether wildcards match names that begin with a @racket[#\.]
  character.  If @racket[#t], the wildcards will match dotfiles.  If
  @racket[#f], use a glob such as @racket{.*} to match dotfiles explicitly.
}

