(define-syntax my-let*
  (syntax-rules ()
    [(_ () body ...) (let () body ...)]
    [(_ ([x v] binding ...) body ...)
     (let ([x v])
       (my-let* (binding ...) body ...))]))

(my-let* ([x 42]
          [x (+ x 1)])
  x)
]}


